'use strict'

/**
 * 被管服务样例：一个 http 客户端，用来验证 after 依赖顺序。
 * 端口跟随 APP1_PORT，保持与 app1.js 一致。
 */

const http = require('http')

const PORT = parseInt(process.env.APP1_PORT || '3456', 10)

http.get(`http://127.0.0.1:${PORT}/`, res => {
  res.on('data', chunk => {
    console.log(chunk.toString('utf8'))
  })

  res.on('end', () => {
    console.log(' -- end --')
  })

}).on('error', err => {
  // 只打一行：服务还没起来时这里会刷 ECONNREFUSED，整段堆栈没有信息量
  console.error(`hcli: ${err.code || err.message}`)
  process.exit(1)
})
